set -eu
node - <<'JS'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const cp = require('node:child_process');
const crypto = require('node:crypto');
assert.ok(process.getuid() >= 10000);
assert.ok(process.env.LD_PRELOAD.endsWith('/libarxdpreload.so'));
const path = process.env.PREFIX + '/share/arxd-node-probe.txt';
fs.writeFileSync(path, 'Arxd Node π\n');
assert.equal(fs.readFileSync(path, 'utf8'), 'Arxd Node π\n');
fs.unlinkSync(path);
const child = cp.execFileSync(process.execPath, ['-e', 'process.stdout.write(String(6 * 7))'], {encoding:'utf8'});
assert.equal(child, '42');
const clean = cp.execFileSync(process.execPath, ['-e', 'process.stdout.write(String(8 * 8))'], {env:{}, encoding:'utf8'});
assert.equal(clean, '64');
const shell = cp.execSync('node -e "process.stdout.write(String(6 * 7))"', {encoding:'utf8'});
assert.equal(shell, '42');
const python = cp.execFileSync('python', ['-c', 'print(7 * 8)'], {encoding:'utf8'}).trim();
assert.equal(python, '56');
console.log(JSON.stringify({probe:'node',version:process.version,executable:process.execPath,uid:process.getuid(),child,cleanChild:clean,shellChild:shell,pythonChild:python,sha256:crypto.createHash('sha256').update('arxd').digest('hex')}));
JS
